-- Appended to the isolated applications.sql fixture, inside its transaction.
select public.save_sowing_group(pg_temp.group_data(),pg_temp.stages());
select public.save_sowing_group(pg_temp.group_data()||'{"id":"91000000-0000-4000-8000-000000000002","name":"Segundo grupo"}',pg_temp.stages());
select public.create_application_order(pg_temp.order_data()||'{"source_group_id":"91000000-0000-4000-8000-000000000001"}',pg_temp.stages(),pg_temp.mixture());
select pg_temp.assert_true((select selection_origin='group' and source_group_id='91000000-0000-4000-8000-000000000001' and source_group_name='Grupo manual' from public.application_orders),'grupo de origen persistido con nombre de servidor');
select pg_temp.assert_true((select bool_and(jsonb_array_length(group_memberships_snapshot)=2) from public.application_targets),'cada destino conserva varias pertenencias');
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000002')||'{"source_group_name":"Nombre falsificado","selection_origin":"group"}',array['80000000-0000-4000-8000-000000000001']::uuid[],pg_temp.mixture());
select pg_temp.assert_true((select selection_origin='individual' and source_group_id is null and source_group_name is null from public.application_orders where id='90000000-0000-4000-8000-000000000002'),'captura individual no hereda origen ni nombre enviado por cliente');
select pg_temp.assert_true((select jsonb_array_length(group_memberships_snapshot)=2 from public.application_targets where order_id='90000000-0000-4000-8000-000000000002'),'individual conserva pertenencias sin presentarse como receta de grupo');
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000003'),pg_temp.stages(),pg_temp.mixture());
select pg_temp.assert_true((select selection_origin='manual' and source_group_id is null from public.application_orders where id='90000000-0000-4000-8000-000000000003'),'selección manual de varios lotes conserva origen propio');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004')||'{"source_group_id":"91000000-0000-4000-8000-000000000001"}',array['80000000-0000-4000-8000-000000000001']::uuid[],pg_temp.mixture())$q$,'todos sus destinos','grupo incompleto se rechaza en servidor');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004')||'{"source_group_id":"91000000-0000-4000-8000-000000000099"}',pg_temp.stages(),pg_temp.mixture())$q$,'grupo activo','grupo inexistente rechazado');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data()||'{"source_group_id":"91000000-0000-4000-8000-000000000002"}',pg_temp.stages(),pg_temp.mixture())$q$,'UUID','reintento no cambia el grupo de origen');
select public.save_sowing_group(pg_temp.group_data()||'{"name":"Grupo renombrado"}',array['80000000-0000-4000-8000-000000000001']::uuid[]);
select pg_temp.assert_true((select source_group_name='Grupo manual' from public.application_orders where id='90000000-0000-4000-8000-000000000001'),'renombre conserva nombre histórico de origen');
select pg_temp.assert_true((select bool_and(group_memberships_snapshot @> '[{"id":"91000000-0000-4000-8000-000000000001","name":"Grupo manual"}]'::jsonb) from public.application_targets),'retiro de integrante no modifica pertenencias guardadas');
select public.save_sowing_group(pg_temp.group_data()||'{"name":"Grupo renombrado","active":false}',array[]::uuid[]);
select pg_temp.assert_true(public.create_application_order(pg_temp.order_data()||'{"source_group_id":"91000000-0000-4000-8000-000000000001"}',pg_temp.stages(),pg_temp.mixture())='90000000-0000-4000-8000-000000000001'::uuid,'reintento idéntico sigue válido tras desactivar grupo');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004')||'{"source_group_id":"91000000-0000-4000-8000-000000000001"}',pg_temp.stages(),pg_temp.mixture())$q$,'grupo activo','grupo inactivo no emite nueva aplicación');
select public.perform_application_targets('90000000-0000-4000-8000-000000000001',array[(select id from public.application_targets where order_id='90000000-0000-4000-8000-000000000001' and stage_id='80000000-0000-4000-8000-000000000001')],'{"changed":false,"actual_date":"2026-01-04"}');
select pg_temp.assert_true((select count(*) filter(where status='performed')=1 and count(*) filter(where status='indicated')=1 from public.application_targets where order_id='90000000-0000-4000-8000-000000000001'),'origen de grupo conserva realización parcial por destino');
select pg_temp.assert_true((select selection_origin='group' from public.application_orders where id='90000000-0000-4000-8000-000000000001'),'realizar un destino no cambia el origen grupal');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select source_group_name='Grupo manual' from public.application_orders where id='90000000-0000-4000-8000-000000000001'),'lector asignado recupera origen histórico');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004'),pg_temp.stages(),pg_temp.mixture())$q$,'administrador','lector no crea registros con origen');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000003';
select pg_temp.assert_true((select count(*)=0 from public.application_orders),'RLS oculta órdenes y origen fuera de asignación');
select pg_temp.assert_true((select count(*)=0 from public.application_targets),'RLS oculta snapshots de pertenencia fuera de asignación');
reset role;
set local rcfito.application_write='perform';
select pg_temp.expect_error($q$update public.application_targets set status='performed',actual_date='2026-01-04',actual_water_l_ha=100,group_memberships_snapshot='[]' where order_id='90000000-0000-4000-8000-000000000001' and status='indicated'$q$,'pertenencias históricas','guarda protege snapshot de pertenencias frente a escritura privilegiada');
rollback;
